 (R/'RESULT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');S=REPO/'src/research_results/phase235_20261027';assert not S.exists();S.mkdir(parents=True)
 for n in ['RESULT.md','TABLE1.csv','TABLE2.csv','TABLE3.csv','P_COMPARISON_POINTS.csv','L8_STRATA_DIFFERENCES.csv','INDEPENDENT_ACCEPTANCE.json','COST_AND_IDENTITY_RECEIPT.json']:shutil.copy2(R/n,S/n)
 save('LOCAL_CODE_SHA.json',{p.name:sha(p) for p in (REPO/'src/tools').glob('*phase235.py')});(R/'HANDOFF.md').write_text('Current delivery: COMPLETE. OneL8bias fit, SP232bias reused, allSourceRaw234 andSPvalB3232exact, independentroot/metrics/bootstrap/ledger passed. No ongoingprocess orautomatic236. Cacheonlyshared/phase235_20261027/cache retained; nohistoricalcleanup/workdirsync/autopush. SeeRESULT.md andfinalmanifest.\n',encoding='utf-8');manifest={p.relative_to(R).as_posix():{'SHA':sha(p),'bytes':p.stat().st_size} for p in R.rglob('*') if p.is_file() and p.name not in ['DELIVERY_MANIFEST.json','DELIVERY_COMPLETE.json']};save('DELIVERY_MANIFEST.json',manifest);combined=tr['remote_formal_bytes']+sum(p.stat().st_size for p in R.rglob('*') if p.is_file())+sum(p.stat().st_size for p in S.rglob('*') if p.is_file());assert combined<512*1024**2;save('DELIVERY_COMPLETE.json',{'status':'complete','epoch':time.time(),'manifest_SHA':sha(R/'DELIVERY_MANIFEST.json'),'files':len(manifest),'combined_formal_bytes':combined,'temporary_cache_bytes_separate':tr['remote_temporary_cache_bytes'],'summary':str(S)});print(json.dumps({'status':'complete','TABLE3':t3}))
